/* Custom PNG icons (Tickets, Pending, In Progress, Assignment, Active, Audit Activity), embedded as data URIs and drawn as CSS masks so they take the surrounding text colour. Used by App.icon() in icons.js for these names. */
(function () {
  const IMG = {
    milestone: 'data:image/png;base64,',
    checkcircle: 'data:image/png;base64,',
    ticket: 'data:image/png;base64,',
    clock: 'data:image/png;base64,',
    progress: 'data:image/png;base64,',
    assignment: 'data:image/png;base64,',
    active: 'data:image/png;base64,',
    audit: 'data:image/png;base64,',
  };
  App.iconImages = IMG;
  const css = Object.keys(IMG).map((k) => `.icon-img.ic-${k}{-webkit-mask-image:url(${IMG[k]});mask-image:url(${IMG[k]})}`).join("");
  const st = document.createElement('style');
  st.textContent = ".icon-img{display:inline-block;background-color:currentColor;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center;-webkit-mask-size:contain;mask-size:contain}" + css;
  document.head.appendChild(st);
})();
